using System.Linq;
using System.Collections.Generic;
using UnityEngine;
namespace HarborValeGreybox.Racing {
public sealed class GarageFleetDisplay:MonoBehaviour {
 readonly List<GameObject> models=new List<GameObject>();string signature;float timer;
 public static void Hook(){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="HarborVale_CityMap")new GameObject("Owned garage parking bays").AddComponent<GarageFleetDisplay>();}
 void Update(){timer-=Time.deltaTime;if(timer>0)return;timer=1;var director=RivalRaceDirector.Instance;var garage=PhysicalGarage.Instance;if(director?.Ready!=true||garage?.Ready!=true)return;var f=director.Trial.Store.Profile.fleet;int activeBay=garage.InBay(director.Trial.vehicle.transform.position)?Mathf.RoundToInt(garage.Building.InverseTransformPoint(director.Trial.vehicle.transform.position).x/5.8f):0;string key=f.selectedId+"/"+activeBay+"/"+string.Join(";",f.cars.Where(c=>c.owner=="player").Select(c=>c.id+":"+c.engineId));if(key==signature)return;signature=key;foreach(var g in models)if(g!=null){g.SetActive(false);Destroy(g);}models.Clear();var slots=new[]{-1,1,0}.Where(i=>i!=activeBay).Take(2).ToArray();var parked=f.cars.Where(c=>c.owner=="player"&&c.id!=f.selectedId).Take(slots.Length).ToArray();for(int i=0;i<parked.Length;i++){var c=parked[i];string model=VehicleLineup.Model(c);var spec=VehicleLineup.IsNew(model)?VehicleLineup.Find(model):null;var g=Instantiate(Resources.Load<GameObject>(model=="car_finch"?"RivalsFinch":model));g.name="Parked owned car | "+c.id;foreach(var script in g.GetComponentsInChildren<MonoBehaviour>())Destroy(script);foreach(var collider in g.GetComponentsInChildren<Collider>()){collider.enabled=false;Destroy(collider);}g.transform.SetParent(transform,false);g.transform.SetPositionAndRotation(garage.Building.TransformPoint(new Vector3(slots[i]*5.8f,.08f,0)),garage.Building.rotation);foreach(var pivot in g.GetComponentsInChildren<Transform>().Where(t=>t.name.EndsWith("wheel pivot"))){var p=pivot.localPosition;p.y-=.12f;pivot.localPosition=p;}var shell=g.AddComponent<BoxCollider>();shell.center=new Vector3(0,spec==null?.84f:spec.height*.5f+.08f,0);shell.size=spec==null?new Vector3(1.58f,1.18f,3.9f):new Vector3(spec.width-.12f,spec.height-.28f,spec.length-.12f);var body=g.AddComponent<Rigidbody>();body.isKinematic=true;var label=new GameObject("Owned vehicle bay label");label.transform.SetParent(g.transform,false);label.transform.localPosition=new Vector3(0,2.1f,1.4f);var text=label.AddComponent<TextMesh>();text.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");text.fontSize=40;text.characterSize=.045f;text.anchor=TextAnchor.MiddleCenter;text.alignment=TextAlignment.Center;text.text=(spec==null?"ASTER FINCH":spec.name.ToUpperInvariant())+"\n"+(director.Trial.Store.HasEngine(c.id)?"OWNED / ENGINE FITTED":"OWNED / ENGINE REMOVED");label.GetComponent<Renderer>().sharedMaterial=text.font.material;models.Add(g);}}
}
}
